function compute(state) {
  var Q = state.Q, K = state.K, V = state.V;
  var dk = K[0].length;
  if (Q[0].length !== dk) throw new Error('Q and K need the same number of columns');
  if (K.length !== V.length) throw new Error('K and V need the same number of rows');
  var s = state.scale ? 1 / Math.sqrt(dk) : 1;
  var scores = Q.map(function (q) { return K.map(function (k) { var t = 0; for (var i = 0; i < dk; i++) t += q[i] * k[i]; return t * s; }); });
  var weights = scores.map(function (r) { var m = Math.max.apply(null, r); var e = r.map(function (x) { return Math.exp(x - m); }); var z = e.reduce(function (a, b) { return a + b; }, 0); return e.map(function (x) { return x / z; }); });
  var output = weights.map(function (w) { return V[0].map(function (_, j) { return w.reduce(function (a, wi, i) { return a + wi * V[i][j]; }, 0); }); });
  return { outputs: { scores: scores, weights: weights, output: output,
                      qlabels: Q.map(function (_, i) { return 'q' + (i + 1); }), klabels: K.map(function (_, i) { return 'k' + (i + 1); }) },
           intermediates: [ { label: 'scores', value: scores, note: 'QK^T, scaled if on' }, { label: 'weights', value: weights, note: 'softmax of each row' } ] };
}
